#include <string>
#include <vector>

using namespace std;

class Solution {
public:
    int maximumRemovals(string s, string p, vector<int>& removable) {
        int n = s.size(), m = p.size(), rSize = removable.size();
        vector<bool> removed(n, false);

        auto check = [&](int k) -> bool {
            for (int i = 0; i < k; ++i) removed[removable[i]] = true;
            int j = 0;
            for (int i = 0; i < n && j < m; ++i) {
                if (!removed[i] && s[i] == p[j]) {
                    j++;
                }
            }
            for (int i = 0; i < k; ++i) removed[removable[i]] = false;
            return j == m;
        };

        int low = 0, high = rSize, ans = 0;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int maximumRemovals(String s, String p, int[] removable) {
        int n = s.length(), m = p.length(), rSize = removable.length;
        boolean[] removed = new boolean[n];

        int low = 0, high = rSize, ans = 0;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            for (int i = 0; i < mid; ++i) removed[removable[i]] = true;

            int j = 0;
            for (int i = 0; i < n && j < m; ++i) {
                if (!removed[i] && s.charAt(i) == p.charAt(j)) {
                    j++;
                }
            }
            for (int i = 0; i < mid; ++i) removed[removable[i]] = false;

            if (j == m) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}

