var maximumRemovals = function(s, p, removable) {
    const n = s.length, m = p.length, rSize = removable.length;
    const removed = new Uint8Array(n);

    let low = 0, high = rSize, ans = 0;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        for (let i = 0; i < mid; ++i) removed[removable[i]] = 1;

        let j = 0;
        for (let i = 0; i < n && j < m; ++i) {
            if (removed[i] === 0 && s[i] === p[j]) {
                j++;
            }
        }
        for (let i = 0; i < mid; ++i) removed[removable[i]] = 0;

        if (j === m) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
};
